const counters: Partial<Record<AffirmationCategory, number>> = {};

export const BUILTIN_AFFIRMATIONS: readonly Affirmation[] = CATALOG.map((row) => {
  const n = (counters[row.category] ?? 0) + 1;
  counters[row.category] = n;
  return {
    id: [row.category, '-', String(n).padStart(3, '0')].join(''),
    source: 'builtin' as const,
    category: row.category,
    en: row.en,
    es: row.es,
  };
});

export function affirmationText(row: Affirmation, lang: string): string {
  return lang.startsWith('es') ? row.es || row.en : row.en || row.es;
}

export function affirmationsByCategory(category: AffirmationCategory): Affirmation[] {
  return BUILTIN_AFFIRMATIONS.filter((row) => row.category === category);
}

export function findBuiltinAffirmation(id: string): Affirmation | undefined {
  return BUILTIN_AFFIRMATIONS.find((row) => row.id === id);
}

export function customToAffirmation(row: { id: string; textEn: string; textEs: string }): Affirmation {
  return {
    id: row.id,
    source: 'custom',
    en: row.textEn,
    es: row.textEs,
  };
}

export function affirmationRefKey(source: AffirmationSource, id: string): string {
  return `${source}:${id}`;
}

export function resolveAffirmationRef(
  source: AffirmationSource,
  refId: string,
  customs: readonly Affirmation[],
): Affirmation | undefined {
  if (source === 'builtin') return findBuiltinAffirmation(refId);
  return customs.find((row) => row.id === refId);
}

/**
 * Welcome-pill cycle: favorites first, then custom lines, then the bundled
 * 460. Deduped. Offline catalog is this module only — no network fetch.
 */
export function buildAffirmationCyclePool(
  customs: readonly Affirmation[],
  favoriteRefs: ReadonlyArray<{ source: AffirmationSource; refId: string }>,
): Affirmation[] {
  const seen = new Set<string>();
  const out: Affirmation[] = [];
  const push = (row: Affirmation | undefined) => {
    if (!row) return;
    const key = affirmationRefKey(row.source, row.id);
    if (seen.has(key)) return;
    seen.add(key);
    out.push(row);
  };
  for (const fav of favoriteRefs) {
    push(resolveAffirmationRef(fav.source, fav.refId, customs));
  }
  for (const row of customs) push(row);
  for (const row of BUILTIN_AFFIRMATIONS) push(row);
  return out;
}
